SELECT * FROM public.nocode_application WHERE deleted=0 AND (app_name ILIKE #{search} ESCAPE '!' OR app_code ILIKE #{search} ESCAPE '!')
AND creator=#{creator}
AND category=#{category}
ORDER BY update_time DESC,id DESC

SELECT DISTINCT category FROM public.nocode_application WHERE deleted=0 AND category <> ''
AND creator=#{creator}
ORDER BY category
